class Box
    public define content as integer;
endClass

algorithm TryIndependentCopy
    define initialValue as integer;
    define newValue as integer;
    define original as Box;
    define cloned as Box;
    read initialValue;
    read newValue;
    original <- new Box();
    original.content <- initialValue;
    cloned <- copy(original);
    cloned.content <- newValue;
    write original.content;
endAlgorithm
